const som::SomMetaTree& d00SolutionBlueprintMetaTree() {
  static const std::unique_ptr<som::SomMetaTree> cached = []() {
    auto n = std::make_unique<som::SomMetaNode>();
    n->className = "D00SolutionBlueprint";
    n->sectionId = "SBP";
    n->kind = som::kSomMetaKindSection;
    n->typeName = "D00SolutionBlueprint";
    n->docComment = "The complete Solution Blueprint (SBP) document.\n\nContains a [DocumentControl] header block and the SBP sections, sequenced\nper the public-standards order (§4 of the redesign proposal).";
    n->classDocComment = "The complete Solution Blueprint (SBP) document.\n\nContains a [DocumentControl] header block and the SBP sections, sequenced\nper the public-standards order (§4 of the redesign proposal).";
    n->document = som::SomDocMeta{};
    n->document->name = "Solution Blueprint";
    n->document->description = "Comprehensive specification document covering all aspects of the system from current landscape through target operating model, information model, solution architecture, security, experience design, quality & acceptance, and delivery / transition planning.";
    (*n).extra.push_back(som::SomMetaExtra{"StandardReferences", som::jsonParse("{\"standards\":[\"ISO/IEC/IEEE 29148:2018 §6 — specification document structure\",\"BABOK v3 — solution scope and blueprint\"],\"connotation\":\"The umbrella specification aggregating every Solution Blueprint section, from current landscape through target operating model, architecture, quality, and delivery and transition.\"}", nullptr)});
    std::vector<std::string> stack;
    stack.push_back("D00SolutionBlueprint");
    buildD00SolutionBlueprintChildren(*n, stack);
    return som::SomMetaTree::create(std::move(n));
  }();
  return *cached;
}
NavD00SolutionBlueprint d00SolutionBlueprintMetaNav(const som::SomMetaTree& tree) {
  return NavD00SolutionBlueprint{som::SomMetaRef(&tree, "SBP")};
}
IdD00SolutionBlueprint d00SolutionBlueprintMetaId(const som::SomMetaTree& tree) {
  return IdD00SolutionBlueprint{som::SomMetaRef(&tree, "SBP")};
}

const som::SomMetaTree& d01CurrentLandscapeAssessmentMetaTree() {
  static const std::unique_ptr<som::SomMetaTree> cached = []() {
    auto n = std::make_unique<som::SomMetaNode>();
    n->className = "D01CurrentLandscapeAssessment";
    n->sectionId = "CLA";
    n->kind = som::kSomMetaKindSection;
    n->typeName = "D01CurrentLandscapeAssessment";
    n->docComment = "CLA00 Current Landscape Assessment.\n\nDetailed analysis of the current state: existing systems, business\nprocesses, pain points, data landscape, operational metrics, risks,\nand the inventory / migration plan for the systems being replaced.";
    n->classDocComment = "CLA00 Current Landscape Assessment.\n\nDetailed analysis of the current state: existing systems, business\nprocesses, pain points, data landscape, operational metrics, risks,\nand the inventory / migration plan for the systems being replaced.";
    n->document = som::SomDocMeta{};
    n->document->name = "Current Landscape Assessment";
    n->document->description = "Detailed analysis of the current systems and processes the target system will replace — landscape, pain points, metrics, risks, replacement inventory, and migration considerations.";
    n->document->basedOn.push_back("D00SolutionBlueprint");
    (*n).extra.push_back(som::SomMetaExtra{"StandardReferences", som::jsonParse("{\"standards\":[\"BABOK v3 — current-state analysis\",\"ISO/IEC/IEEE 29148:2018 — as-is system constraints\"],\"connotation\":\"The current-state analysis of the systems and processes the target system will replace, covering landscape, pain points, metrics, risks, and replacement inventory.\"}", nullptr)});
    std::vector<std::string> stack;
    stack.push_back("D01CurrentLandscapeAssessment");
    buildD01CurrentLandscapeAssessmentChildren(*n, stack);
    return som::SomMetaTree::create(std::move(n));
  }();
  return *cached;
}
